import { addDays, format, getDay, startOfMonth } from 'date-fns';

/** Week starts Saturday (Saudi-style). JS: 0=Sun … 6=Sat */
function daysFromWeekStartSaturday(d: Date): number {
    return (getDay(d) + 1) % 7;
}

export function buildCalendarGrid(year: number, month0: number): Date[] {
    const monthStart = startOfMonth(new Date(year, month0, 1));
    const offset = daysFromWeekStartSaturday(monthStart);
    const gridStart = addDays(monthStart, -offset);
    const cells: Date[] = [];
    for (let i = 0; i < 42; i++) {
        cells.push(addDays(gridStart, i));
    }
    return cells;
}

export function isSameMonth(a: Date, b: Date): boolean {
    return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth();
}

export function dateKey(d: Date): string {
    return format(d, 'yyyy-MM-dd');
}

export type HolidayRangeRow = {
    id: number;
    name: string;
    start: string;
    end: string;
};

export function parseHolidayListRow(row: Record<string, unknown>): HolidayRangeRow | null {
    const id = Number(row.id);
    if (Number.isNaN(id)) return null;
    const name = String(row.vacation_type ?? row.name ?? row.title ?? '').trim();
    const start = String(row.start_date ?? '');
    const endRaw = String(row.end_date ?? row.start_date ?? '');
    if (!start) return null;
    return { id, name: name || 'إجازة', start, end: endRaw || start };
}

/** Map yyyy-MM-dd -> { id, name } (last write wins for overlapping ranges) */
export function rangesToDayMap(rows: HolidayRangeRow[]): Map<string, { id: number; name: string }> {
    const map = new Map<string, { id: number; name: string }>();
    for (const row of rows) {
        let d = new Date(row.start + 'T12:00:00');
        const end = new Date(row.end + 'T12:00:00');
        if (Number.isNaN(d.getTime()) || Number.isNaN(end.getTime())) continue;
        while (d <= end) {
            map.set(dateKey(d), { id: row.id, name: row.name });
            d = addDays(d, 1);
        }
    }
    return map;
}
